scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 420) @Event420;
	
	Return;
	
@Event420:	
	If ($Talkmap070 == 0) @Talk0;
	If ($Talkmap070 == 1) @Talk1;
	
@Talk0:	
	Say("张琳心：小桥流水人家，想不到在豫中也能看到类似江南的风景。", 21);
	Say("独孤剑：是不是想家啦？", 2);
	Say("张琳心：没有……", 21);
	Say("独孤剑：其实我也很想衡山，我下山这么久了，也不知师弟师妹的近况怎样……", 1);
	Assign($Talkmap070, 1);
	Return;
@Talk1:
	Say("独孤剑：也许是我太自私，让你一个女孩子跟着东奔西跑，不仅辛苦，还要冒风险，实在太难为你了。", 1);
	Say("张琳心：没有啊，我是心甘情愿的！只要……能和你在一起，我……天涯海角都愿意去！什么艰险我都不怕……", 21);
	Say("独孤剑：琳儿……", 2);	
	Return;

scripts.钓鱼翁对话.txt:
// 	与钓鱼翁的对话

	If ($Talkdiaoyu == 0) @Talk0;
	If ($Talkdiaoyu == 1) @Talk1;
@Talk0:
	Say("钓翁：鱼儿、鱼儿，快上钩吧。", 0);
	Say("独孤剑：老翁，你钩上没饵，鱼怎么会上钩呢？", 2);
	Say("钓翁：什么？这鱼太狡猾了，每次都是偷吃鱼饵却不上钩，真是气死我了！", 0);
	Assign($Talkdiaoyu, 1);
	Return;
@Talk1:
	Say("钓翁：这鱼太狡猾了，每次都是偷吃鱼饵却不上钩，真是气死我了！", 0);
	Return;

